testsCode:
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { criarContador } from './solution.mjs';

test('contador começa com o valor inicial', () => {
  const contador = criarContador(10);
  assert.equal(contador.total(), 10);
});

test('somar acumula os pontos', () => {
  const contador = criarContador(0);
  contador.somar(5);
  contador.somar(3);
  assert.equal(contador.total(), 8);
});

test('cada contador é dono dos próprios pontos', () => {
  const primeiro = criarContador(10);
  const segundo = criarContador(0);
  primeiro.somar(5);
  segundo.somar(2);
  assert.equal(primeiro.total(), 15);
  assert.equal(segundo.total(), 2);
});

test('zerar volta os pontos para zero', () => {
  const contador = criarContador(7);
  contador.somar(10);
  contador.zerar();
  assert.equal(contador.total(), 0);
});

solutionCode:
export function criarContador(inicial) {
  return {
    pontos: inicial,
    somar(valor) {
      this.pontos = this.pontos + valor;
    },
    zerar() {
      this.pontos = 0;
    },
    total() {
      return this.pontos;
    }
  };
}
